import {poweredDevice,logic} from './bus-electrical.js';
import {UARTReceiver,UARTTransmitter} from './uart-lines.js';
export const BLUETOOTH_PART={name:'Bluetooth · HC-05 görünüm',asset:'bluetooth-hc05.svg',scale:1,license:'CC0',source:'https://www.deshide.com/product-details_HC-05.html',category:'Girişler',detail:'3.3 V · UART 9600 8N1 · sanal ağ',width:122,height:100,pins:['VCC','GND','TX','RX','STATE'],pinDefs:['VCC','GND','TX','RX','STATE'].map((id,i)=>({id,x:14+i*23,y:94,side:'bottom'}))};
// CF-BLE-UART is a documented simulator peripheral, not an HC-05 firmware clone.
export class VirtualBluetooth {
 constructor({cpu,solution,changed=()=>{}}){Object.assign(this,{cpu,solution,changed});this.devices=new Map();this.events=[];this.drives=new Map();this.dirty=false;}
 record(kind,id,detail){this.events.push({cycle:this.cpu.cycles,kind,id,detail});if(this.events.length>128)this.events.shift();}
 drive(id,pin,high){const key=id+':'+pin;if(this.drives.get(key)===high)return;this.drives.set(key,high);this.dirty=true;this.changed();}
 format(d){return{period:16000000/(d.component.params.baud??9600),bits:8,stops:1,parity:null};}
 update(project){for(const[id,d]of this.devices)if(!project.components.some(c=>c.id===id&&c.type==='bluetooth')){this.disconnect(id);d.rx.cancel();d.tx.cancel();this.devices.delete(id);for(const p of ['TX','STATE'])this.drives.delete(id+':'+p);}
  for(const c of project.components.filter(c=>c.type==='bluetooth')){let d=this.devices.get(c.id);if(!d){d={id:c.id,component:c,powered:false,connected:null,received:[],errors:0};d.tx=new UARTTransmitter(this.cpu,h=>this.drive(d.id,'TX',h));d.rx=new UARTReceiver(this.cpu,()=>logic(this.voltage(d.id,'RX'),3.3),()=>d.powered?this.format(d):null,f=>this.receive(d,f));this.devices.set(c.id,d);}if(d.component.params.baud!==c.params.baud){d.tx.cancel();d.rx.cancel();}d.component=c;}this.observe();}
 voltage(id,pin){const s=this.solution();return s?.voltages.get(s.netlist.net(id+':'+pin));}
 observe(){for(const d of this.devices.values()){const dc=this.solution();if(!dc)continue;const p=poweredDevice(dc,d.id,{min:3,max:3.6}),rx=this.voltage(d.id,'RX');d.safe=!Number.isFinite(rx)||rx>=-.3&&rx<=3.6;if(d.powered&&(!p.powered||!d.safe)){this.disconnect(d.id);d.rx.cancel();d.tx.cancel();}d.powered=p.powered&&d.safe;d.voltage=p.voltage;if(!d.powered){this.drive(d.id,'TX',null);this.drive(d.id,'STATE',null);continue;}if(!d.tx.busy)this.drive(d.id,'TX',true);this.drive(d.id,'STATE',!!d.connected);d.rx.observe();}}
 scan(){this.observe();const list=[...this.devices.values()].filter(d=>d.powered&&!d.connected).map(d=>({id:d.id,name:d.component.params.name,transport:'Sanal BLE UART',baud:d.component.params.baud??9600}));this.record('scan','$pc',list.map(d=>d.id).join(', '));return list;}
 connect(id,peer='$pc'){this.observe();const d=this.devices.get(id),other=this.devices.get(peer);if(!d?.powered||d.connected||peer!== '$pc'&&(!other?.powered||other.connected||peer===id))throw Error('Sanal cihaz erişilebilir değil veya bağlı.');d.connected=peer;if(other)other.connected=id;this.drive(id,'STATE',true);if(other)this.drive(peer,'STATE',true);this.record('connect',id,peer);}
 disconnect(id){const d=this.devices.get(id);if(!d)return;const peer=d.connected;if(peer){const other=this.devices.get(peer);if(other){other.connected=null;other.tx.cancel();other.rx.cancel();this.drive(peer,'STATE',false);}this.record('disconnect',id,peer);}d.connected=null;d.tx.cancel();d.rx.cancel();this.drive(id,'STATE',d.powered?false:null);}
 send(id,text){this.observe();const d=this.devices.get(id);if(!d?.powered||d.connected!=='$pc')throw Error('Önce sanal bilgisayarı cihaza bağlayın.');if(typeof text!=='string'||!text.length||new TextEncoder().encode(text).length>1024)throw Error('Bluetooth mesajı: 1–1024 bayt.');const bytes=new TextEncoder().encode(text);if(d.tx.queue.length+bytes.length>4096)throw Error('Bluetooth TX kuyruğu dolu.');for(const b of bytes)d.tx.enqueue(b,this.format(d));this.record('pc-write',id,text);}
 receive(d,f){if(!d.powered||!d.connected)return;if(f.error){d.errors++;this.record('uart-error',d.id,f.error);return;}if(d.connected==='$pc'){d.received.push(f.value);if(d.received.length>4096)d.received.shift();this.record('notification',d.id,f.value);}else{const peer=this.devices.get(d.connected);if(peer?.powered&&peer.connected===d.id)peer.tx.enqueue(f.value,this.format(peer));}}
 command({action,id,peer,text}){if(action==='scan')return this.scan();if(action==='connect')return this.connect(id,peer);if(action==='disconnect')return this.disconnect(id);if(action==='send')return this.send(id,text);throw Error('Bluetooth komutu geçersiz.');}
 drivers(){return[...this.drives].filter(([,h])=>h!==null).map(([endpoint,h])=>({endpoint,voltage:h?3.3:0,ohms:100}));}
 snapshot(){this.observe();return{virtual:true,devices:Object.fromEntries([...this.devices].map(([id,d])=>[id,{name:d.component.params.name,powered:d.powered,voltage:d.voltage,safe:d.safe,connected:d.connected,baud:d.component.params.baud??9600,received:new TextDecoder().decode(Uint8Array.from(d.received)),errors:d.errors}])),events:[...this.events]};}
 dispose(){for(const d of this.devices.values()){d.rx.cancel();d.tx.cancel();}this.devices.clear();this.drives.clear();}
}
